re", "lf": "Glabre", "le": "Glabrous", "les": "Glabra", "df": "Surface sans poils.", "de": "A surface without hairs.", "des": "Superficie sin pelos."}, {"cc": "tige__surface", "code": "pubescente", "lf": "Pubescente", "le": "Pubescent", "les": "Pubescente", "df": "Surface portant de petits poils fins.", "de": "A surface bearing small fine hairs.", "des": "Superficie con pequeños pelos finos."}, {"cc": "tige__surface", "code": "tomenteuse", "lf": "Tomenteuse", "le": "Tomentose", "les": "Tomentosa", "df": "Surface très poilue, d''aspect laineux.", "de": "A densely hairy, woolly surface.", "des": "Superficie muy peluda, de aspecto lanoso."}, {"cc": "tige__surface", "code": "hirsute", "lf": "Hirsute", "le": "Hirsute", "les": "Hirsuta", "df": "Surface avec poils raides ou grossiers.", "de": "A surface with stiff or coarse hairs.", "des": "Superficie con pelos rígidos o gruesos."}, {"cc": "tige__surface", "code": "hispide", "lf": "Hispide", "le": "Hispid", "les": "Híspida", "df": "Surface avec poils très rudes ou piquants.", "de": "A surface with very rough or bristly hairs.", "des": "Superficie con pelos muy ásperos o punzantes."}, {"cc": "tige__surface", "code": "scabre", "lf": "Scabre", "le": "Scabrous", "les": "Escabrosa", "df": "Surface rugueuse au toucher.", "de": "A surface rough to the touch.", "des": "Superficie áspera al tacto."}, {"cc": "tige__surface", "code": "glauque", "lf": "Glauque", "le": "Glaucous", "les": "Glauca", "df": "Surface couverte d''une couche cireuse bleuâtre ou blanchâtre.", "de": "A surface covered with a bluish or whitish waxy coating.", "des": "Superficie cubierta por una capa cerosa azulada o blanquecina."}, {"cc": "tige__surface", "code": "cireuse", "lf": "Cireuse", "le": "Waxy", "les": "Cerosa", "df": "Surface couverte de cire.", "de": "A surface covered with wax.", "des": "Superficie cubierta de cera."}, {"cc": "tige__surface", "code": "striee", "lf": "Striée", "le": "Striate", "les": "Estriada", "df": "Surface marquée par de fines lignes longitudinales.", "de": "A surface marked by fine longitudinal lines.", "des": "Superficie marcada por líneas longitudinales finas."}, {"cc": "tige__ramification", "code": "ramification_opposee", "lf": "Ramification opposée", "le": "Opposite branching", "les": "Ramificación opuesta", "df": "Branches placées face à face au même nœud.", "de": "Branches placed opposite each other at the same node.", "des": "Ramas colocadas una frente a otra en el mismo nudo."}, {"cc": "tige__ramification", "code": "ramification_alterne", "lf": "Ramification alterne", "le": "Alternate branching", "les": "Ramificación alterna", "df": "Branches disposées une par une, en alternance.", "de": "Branches arranged one by one in alternation.", "des": "Ramas dispuestas una por una, de forma alterna."}, {"cc": "tige__ramification", "code": "ramification_verticillee", "lf": "Ramification verticillée", "le": "Whorled branching", "les": "Ramificación verticilada", "df": "Trois branches ou plus insérées au même niveau.", "de": "Three or more branches inserted at the same level.", "des": "Tres o más ramas insertadas al mismo nivel."}, {"cc": "tige__ramification", "code": "ramification_dichotomique", "lf": "Ramification dichotomique", "le": "Dichotomous branching", "les": "Ramificación dicotómica", "df": "Axe qui se divise en deux branches à plusieurs reprises.", "de": "An axis repeatedly dividing into two branches.", "des": "Eje que se divide repetidamente en dos ramas."}, {"cc": "racine__systeme", "code": "racine_pivotante", "lf": "Racine pivotante", "le": "Taproot", "les": "Raíz pivotante", "df": "Racine principale profonde.", "de": "Deep main root.", "des": "Raíz principal profunda."}, {"cc": "racine__systeme", "code": "systeme_racinaire_fibreux_fascicule", "lf": "Système racinaire fibreux / fasciculé", "le": "Fibrous root system", "les": "Sistema radical fibroso / fasciculado", "df": "Système formé de nombreuses racines fines de taille proche.", "de": "A system made of many fine roots of similar size.", "des": "Sistema formado por muchas raíces finas de tamaño similar."}, {"cc": "racine__specialisee", "code": "racine_adventive", "lf": "Racine adventive", "le": "Adventitious root", "les": "Raíz adventicia", "df": "Racine née d''un endroit inhabituel.", "de": "Root arising from an unusual place.", "des": "Raíz nacida de un lugar inusual."}, {"cc": "racine__specialisee", "code": "racine_aerienne", "lf": "Racine aérienne", "le": "Aerial root", "les": "Raíz aérea", "df": "Racine au-dessus du sol.", "de": "Root above the ground.", "des": "Raíz por encima del suelo."}, {"cc": "racine__specialisee", "code": "racine_echasse", "lf": "Racine échasse", "le": "Stilt root", "les": "Raíz zancuda", "df": "Racine de soutien partant de la tige vers le sol, comme une échasse.", "de": "A support root extending from the stem to the ground, like a stilt.", "des": "Raíz de soporte que va del tallo al suelo, como una zanca."}, {"cc": "racine__specialisee", "code": "pneumatophore", "lf": "Pneumatophore", "le": "Pneumatophore", "les": "Neumatóforo", "df": "Racine respiratoire qui sort du sol ou de l''eau, fréquente dans les milieux marécageux.", "de": "A breathing root emerging from soil or water, common in wetlands.", "des": "Raíz respiratoria que emerge del suelo o del agua, común en humedales."}, {"cc": "racine__specialisee", "code": "racine_contrefort", "lf": "Racine contrefort", "le": "Buttress root", "les": "Raíz tablar / contrafuerte", "df": "Grande racine plate qui stabilise certains arbres tropicaux.", "de": "A large plate-like root that stabilizes some tropical trees.", "des": "Raíz grande y plana que estabiliza algunos árboles tropicales."}, {"cc": "racine__specialisee", "code": "racine_tubereuse", "lf": "Racine tubéreuse", "le": "Tuberous root", "les": "Raíz tuberosa", "df": "Racine épaissie, charnue et riche en réserves.", "de": "A thick, fleshy root rich in reserves.", "des": "Raíz engrosada, carnosa y rica en reservas."}, {"cc": "racine__forme", "code": "conique", "lf": "Conique", "le": "Conical", "les": "Cónica", "df": "En forme de cône, large au sommet et rétrécie vers la pointe.", "de": "Cone-shaped, broad at the top and tapering toward the tip.", "des": "Con forma de cono, ancha arriba y estrecha hacia la punta."}, {"cc": "racine__forme", "code": "fusiforme", "lf": "Fusiforme", "le": "Fusiform", "les": "Fusiforme", "df": "Élargie au milieu et rétrécie aux deux extrémités.", "de": "Swollen in the middle and tapered at both ends.", "des": "Ensanchada en el centro y estrechada en ambos extremos."}, {"cc": "racine__forme", "code": "napiforme", "lf": "Napiforme", "le": "Napiform", "les": "Napiforme", "df": "Très renflée au sommet et brusquement rétrécie vers le bas.", "de": "Strongly swollen at the top and abruptly narrowed downward.", "des": "Muy hinchada arriba y estrechada bruscamente hacia abajo."}, {"cc": "racine__forme", "code": "filiforme", "lf": "Filiforme", "le": "Filiform", "les": "Filiforme", "df": "Très fine, semblable à un fil.", "de": "Very slender, thread-like.", "des": "Muy delgada, semejante a un hilo."}, {"cc": "racine__forme", "code": "charnue", "lf": "Charnue", "le": "Fleshy", "les": "Carnosa", "df": "Épaisse, tendre et souvent riche en eau ou réserves.", "de": "Thick, soft, and often rich in water or stored reserves.", "des": "Gruesa, blanda y a menudo rica en agua o reservas."}, {"cc": "racine__forme", "code": "ligneuse", "lf": "Ligneuse", "le": "Woody", "les": "Leñosa", "df": "Dure, riche en tissus de soutien, comme chez beaucoup d''arbres.", "de": "Hard and rich in support tissue, as in many trees.", "des": "Dura y rica en tejidos de soporte, como en muchos árboles."}, {"cc": "racine__symbiose", "code": "mycorhize", "lf": "Mycorhize", "le": "Mycorrhiza", "les": "Micorriza", "df": "Association racine-champignon.", "de": "Root-fungus association.", "des": "Asociación raíz-hongo."}, {"cc": "racine__symbiose", "code": "nodosite_racinaire", "lf": "Nodosité racinaire", "le": "Root nodule", "les": "Nódulo radical", "df": "Structure liée souvent à la fixation de l''azote.", "de": "Structure often linked to nitrogen fixation.", "des": "Estructura a menudo ligada a fijación de nitrógeno."}]'::jsonb) as t(cc text,code text,lf text,le text,les text,df text,de text,des text);
insert into plant_patterns.character_states(character_id,code,label_fr,label_en,label_es,definition_fr,definition_en,definition_es)
 select ch.id, s.code, s.lf, nullif(s.le,''), nullif(s.les,''), nullif(s.df,''), nullif(s.de,''), nullif(s.des,'')
 from _s s join plant_patterns.characters ch on ch.code=s.cc
 on conflict (character_id,code) do nothing;
drop table _c; drop table _s;;
